ALTER TABLE users ADD COLUMN password_enabled INTEGER NOT NULL DEFAULT 1;
ALTER TABLE sessions ADD COLUMN created_at INTEGER NOT NULL DEFAULT 0;
ALTER TABLE study_sets ADD COLUMN parent_notebook_id TEXT REFERENCES study_sets(id) ON DELETE CASCADE;
CREATE INDEX study_sets_parent ON study_sets(parent_notebook_id,deleted);
CREATE TABLE password_resets(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL,used_at INTEGER,created_at INTEGER NOT NULL);
CREATE INDEX password_reset_user ON password_resets(user_id,created_at);
CREATE TABLE oauth_identities(provider TEXT NOT NULL,subject TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at INTEGER NOT NULL,PRIMARY KEY(provider,subject),UNIQUE(user_id,provider));
CREATE TABLE oauth_flows(id TEXT PRIMARY KEY,provider TEXT NOT NULL,state_hash TEXT NOT NULL UNIQUE,nonce TEXT NOT NULL,pkce_verifier TEXT NOT NULL,client_challenge TEXT NOT NULL,expires_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',user_id TEXT REFERENCES users(id) ON DELETE CASCADE,link_user_id TEXT REFERENCES users(id) ON DELETE CASCADE,link_session_hash TEXT,error TEXT,launch_hash TEXT NOT NULL,launched INTEGER NOT NULL DEFAULT 0);
CREATE TABLE notebook_shares(id TEXT PRIMARY KEY,notebook_id TEXT NOT NULL REFERENCES study_sets(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,title TEXT NOT NULL,snapshot TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE INDEX notebook_shares_owner ON notebook_shares(notebook_id,created_at DESC);
INSERT INTO sync_changes(user_id,set_id,version,deleted) SELECT user_id,id,version,deleted FROM study_sets;
